import sys,importlib.abc,importlib,runpy,json
class NoNative(importlib.abc.MetaPathFinder):
 def find_spec(self,fullname,path=None,target=None):
  if fullname.split('.')[0] in {'mlx','mlx_vlm','torch','tensorflow','cupy','jax'}:raise RuntimeError('FORBIDDEN_NATIVE_IMPORT:'+fullname)
sys.meta_path.insert(0,NoNative())
