mods=sorted(p.stem for p in Path('src/mri_rl').glob('*.py') if p.stem!='__init__')
for mod in mods:importlib.import_module('mri_rl.'+mod)
print(json.dumps({'imported_project_modules':len(mods)+1,'native_modules':[x for x in sys.modules if x.split('.')[0] in {'mlx','mlx_vlm','torch','tensorflow','cupy','jax'}]}))

